        for (k = 0; k < 2; k = k + 1) begin
            tg = g[2*k+1] | (p[2*k+1] & g[2*k]);
            tp = p[2*k+1] & p[2*k];
            g[k] = tg; p[k] = tp;
        end
        lt = g[1] | (p[1] & g[0]);
    end
