    reg [31:0] e;
    wire [31:0] p = ~(a_i ^ b_i);
    wire [31:0] g = ~a_i & b_i;
    always @* begin
        e[31] = 1'b1;
        for (k = 30; k >= 0; k = k - 1)
            e[k] = e[k+1] & p[k+1];
    end
