           | (P[7] & P[6] & P[5] & P[4] & G[3])
           | (P[7] & P[6] & P[5] & P[4] & P[3] & G[2])
           | (P[7] & P[6] & P[5] & P[4] & P[3] & P[2] & G[1])
           | (P[7] & P[6] & P[5] & P[4] & P[3] & P[2] & P[1] & G[0]);
    end
    wire s = valid_i & rst_n;
    wire h = ~valid_i & rst_n;
    always @(posedge clk) begin
        valid_o <= s;
        y_o <= (s & lt) | (h & y_o);
    end
